import{_ as a,c as t,o,ag as r}from"./chunks/framework.BSxiluPM.js";const i="/images/posts/keycloak-kakao-idp/01.png",n="/images/posts/keycloak-kakao-idp/02.png",p="/images/posts/keycloak-kakao-idp/03.png",l="/images/posts/keycloak-kakao-idp/04.png",s="/images/posts/keycloak-kakao-idp/06.png",c="/images/posts/keycloak-kakao-idp/07.png",g=JSON.parse('{"title":"Keycloak - Kakao Identity Provider","description":"","frontmatter":{"title":"Keycloak - Kakao Identity Provider","date":"2024-12-27T23:00+09:00","tags":["Keycloak","Kakao"]},"headers":[],"relativePath":"posts/keycloak-kakao-idp.md","filePath":"posts/keycloak-kakao-idp.md","lastUpdated":1762599238000}'),d={name:"posts/keycloak-kakao-idp.md"};function k(u,e,m,h,I,_){return o(),t("div",null,[...e[0]||(e[0]=[r('<p>통합 인증을 위한 IAM 오픈소스인 키클록(Keycloak)에서 카카오 소셜 프로바이더를 IdP(Identity Provider)로 렐름(Realm)에 추가하고 카카오 계정으로 로그인하여 사용자를 인증해보도록 하자. 우선 카카오 소셜 프로바이더는 <a href="https://developers.kakao.com/docs/latest/ko/kakaologin/utilize#oidc" target="_blank" rel="noreferrer">OpenID Connect</a> 규격을 지원하고 있으므로 키클록에서 기본적으로 제공해주고 있는 <u>OpenID Connect v1.0</u> 프로바이더 방식으로 추가하여 로그인 화면에 선택 옵션으로 노출시킬 수 있다.</p><h4 id="카카오-로그인을-위한-rest-api-키와-클라이언트-시크릿" tabindex="-1">카카오 로그인을 위한 REST API 키와 클라이언트 시크릿 <a class="header-anchor" href="#카카오-로그인을-위한-rest-api-키와-클라이언트-시크릿" aria-label="Permalink to &quot;카카오 로그인을 위한 REST API 키와 클라이언트 시크릿&quot;">​</a></h4><p>우선, <a href="https://developers.kakao.com/" target="_blank" rel="noreferrer">카카오 디펠로퍼스</a>에 카카오 계정으로 로그인한 후 애플리케이션을 만들고 카카오 로그인에 대한 설정을 진행하자. 키클록에서 OpenID Connect Provider 설정에 입력할 클라이언트 아이디와 클라이언트 시크릿 정보를 다음의 메뉴에서 확인하도록 하자. 클라이언트 시크릿은 코드 교환 과정에서는 노출되지 않으며 사용자 인증 후 코드를 통해 ID 토큰을 발급받기 위해서 사용된다.</p><ul><li>Client ID : 내 애플리케이션 → 앱 설정 → 앱 키 (REST API 키)</li><li>Client Secret : 내 애플리케이션 → 제품 설정 → 카카오 로그인 → 보안 (Client Secret)</li></ul><h4 id="키클록에-카카오-openid-connect-provider-추가" tabindex="-1">키클록에 카카오 OpenID Connect Provider 추가 <a class="header-anchor" href="#키클록에-카카오-openid-connect-provider-추가" aria-label="Permalink to &quot;키클록에 카카오 OpenID Connect Provider 추가&quot;">​</a></h4><p>Identity Providers 목록에서 <u>OpenID Connect v1.0</u>을 선택하고 <u>Discovery endpoint</u> 에 카카오 로그인의 <a href="https://kauth.kakao.com/.well-known/openid-configuration" target="_blank" rel="noreferrer">OpenID Connect Discovery Metadata</a> 주소를 입력하게 되면 키클록에서는 OpenID Connect 메타데이터를 불러와서 자동으로 입력해준다. 그리고 앞서 카카오 디펠로퍼스에서 확인해두었던 REST API 키와 클라이언트 시크릿을 입력하도록 하자.</p><ul><li>Client ID : 내 애플리케이션 → 앱 설정 → 앱 키 (REST API 키)</li><li>Client Secret : 내 애플리케이션 → 제품 설정 → 카카오 로그인 → 보안 (Client Secret)</li><li>Client assertion signature algorithm : RS256 (Optinal)</li></ul><blockquote><p>카카오에서는 서명 알고리즘으로 RS256 한가지를 지원하므로 굳이 선택할 필요는 없습니다.</p></blockquote><p><img src="'+i+'" alt=""></p><h4 id="카카오-로그인-openid-connect-활성화-설정-및-redirect-uri-추가" tabindex="-1">카카오 로그인 OpenID Connect 활성화 설정 및 Redirect URI 추가 <a class="header-anchor" href="#카카오-로그인-openid-connect-활성화-설정-및-redirect-uri-추가" aria-label="Permalink to &quot;카카오 로그인 OpenID Connect 활성화 설정 및 Redirect URI 추가&quot;">​</a></h4><p>애플리케이션의 제품 설정에서 카카오 로그인과 OpenID Connect 옵션을 활성화하고 키클록에 추가한 IdP 브로커에 표시되는 <u>Redirect URI</u> 주소를 카카오 로그인의 Redirect URI 목록에 추가하면 된다.</p><p><img src="'+n+'" alt=""></p><h4 id="코드-교환-과정에서-pkce-사용하기" tabindex="-1">코드 교환 과정에서 PKCE 사용하기 <a class="header-anchor" href="#코드-교환-과정에서-pkce-사용하기" aria-label="Permalink to &quot;코드 교환 과정에서 PKCE 사용하기&quot;">​</a></h4><p>카카오 소셜 프로바이더는 <u>S256 방식의 PKCE</u>를 지원하므로 코드 교환 과정(Authorization Code Flow)에서 PKCE를 사용할 수 있다.</p><p><img src="'+p+'" alt=""></p><h4 id="사용자-콘솔-로그인-화면에서-카카오-계정으로-로그인" tabindex="-1">사용자 콘솔 로그인 화면에서 카카오 계정으로 로그인 <a class="header-anchor" href="#사용자-콘솔-로그인-화면에서-카카오-계정으로-로그인" aria-label="Permalink to &quot;사용자 콘솔 로그인 화면에서 카카오 계정으로 로그인&quot;">​</a></h4><p>카카오 로그인을 위한 IdP를 추가했으므로 <u>사용자 콘솔(account-console)</u>의 로그인 화면에 카카오 프로바이더가 옵션으로 표시된다. 사용자 콘솔의 로그인 화면에서 카카오 프로바이더 이름을 선택하면 카카오 계정 로그인 화면으로 리다이렉트되며 카카오 계정으로 로그인하고 동의 항목에 따라 진행하면 키클록 사용자로 추가된다. 만약, 아래와 같이 <u>카카오 계정(이메일)에 대한 수집 항목</u>에 동의했다면 사용자 이름과 이메일이 모두 이메일로 설정되며 사용자 정보 입력 단계없이 사용자가 만들어지고 사용자 콘솔 화면이 보인다.</p><p><img src="'+l+'" alt=""></p><h4 id="add-identity-provider-mapper" tabindex="-1">Add Identity Provider Mapper <a class="header-anchor" href="#add-identity-provider-mapper" aria-label="Permalink to &quot;Add Identity Provider Mapper&quot;">​</a></h4><p>카카오 <a href="https://developers.kakao.com/docs/latest/ko/kakaologin/rest-api#request-token-response-id-token" target="_blank" rel="noreferrer">ID 토큰 페이로드</a>에는 수집 동의 항목에 따라 클레임이 포함되어 있는데 이것을 <u>User Attribute</u> 에 추가하기 위해서는 Mapper 설정이 필요하다.</p><ul><li>username : sub</li><li>nickname : nickname</li><li>email : email (기본값)</li></ul><p><img src="'+s+'" alt=""></p><blockquote><p>위와 같이 username 에 대한 Mapper 설정을 추가하지 않는다면 이메일 정보가 username 으로 설정되는 것을 확인할 수 있습니다. 이때, username 에 존재하지 않는 항목을 연결한다면 관리자 콘솔에서 상세 정보를 확인하거나 삭제가 불가능해질 수 있으니 주의가 필요합니다.</p></blockquote><p><img src="'+c+'" alt="카카오 계정으로 추가된 사용자 정보"></p>',24)])])}const C=a(d,[["render",k]]);export{g as __pageData,C as default};
